SELECT     TRUNC(SYSDATE)                                        AS \"Report Date\",     td.TRAN_CODE                                          AS \"Tran Code\",     td.DEPT                                                             ,     d.DEPT_NAME                                           AS \"Department Name\",     d.PROFIT_CALC_TYPE                                    AS \"Accounting Method\",     td.LOC_TYPE                                           AS \"Location Type\",     td.PGM_NAME                                           AS \"Source Program\",     TRUNC(td.TRAN_DATE, 'MM')                             AS \"Period Month\",     p.CURR_454_MONTH                                      AS \"Fiscal 454 Month\",     p.CURR_454_WEEK                                       AS \"Fiscal 454 Week\",     p.START_454_MONTH                                     AS \"Period Start Date\",     p.END_454_MONTH                                       AS \"Period End Date\",     COUNT(*)                                              AS \"Transaction Count\",     ROUND(SUM(NVL(td.TOTAL_COST,   0)), 2)               AS \"RMS Total Cost\",     ROUND(SUM(NVL(td.TOTAL_RETAIL, 0)), 2)               AS \"RMS Total Retail\",     COUNT(DISTINCT td.GL_REF_NO)                          AS \"GL Ref Count\",     SUM(CASE WHEN td.GL_REF_NO IS NULL THEN 1 ELSE 0 END) AS  \"No of GL Ref Count\",     SUM(CASE WHEN td.TOTAL_COST IS NULL THEN 1 ELSE 0 END) AS \"Null Cost Count\" FROM  MFCS_RDS.RDS_WV_TRAN_DATA            td JOIN  MFCS_RDS.RDS_WV_DEPS                 d  ON td.DEPT = d.DEPT LEFT JOIN MFCS_RDS.RDS_WV_PERIOD           p  ON TRUNC(td.TRAN_DATE) = TRUNC(p.VDATE) WHERE     td.TRAN_DATE &gt;= ADD_MONTHS(SYSDATE, -3) GROUP BY     td.TRAN_CODE, td.DEPT, d.DEPT_NAME,     d.PROFIT_CALC_TYPE, td.LOC_TYPE, td.PGM_NAME,     TRUNC(td.TRAN_DATE, 'MM'),     p.CURR_454_MONTH, p.CURR_454_WEEK,     p.START_454_MONTH, p.END_454_MONTH ORDER BY 8, 2, 3</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds: